const items = $input.all();

return items.map((item) => {
  const input = item.json ?? {};
  const body = input.body ?? input;

  const event = body.event;
  const schemaVersion = body.schema_version;
  const repository = body.repository;
  const runId = String(body.run_id ?? '');
  const runAttempt = String(body.run_attempt ?? '');
  const sentAt = body.sent_at;

  const testMode = body.test_mode === true;
  const sideEffectsAllowed =
    body.production_side_effects_allowed === true;

  if (schemaVersion !== 1) throw new Error('Invalid schema_version');
  if (repository !== 'ErenOzusen/eren-muzik-atolyesi') throw new Error('Invalid repository');
  if (!/^\d+$/.test(runId)) throw new Error('Invalid GitHub run_id');
  if (typeof sentAt !== 'string' || Number.isNaN(Date.parse(sentAt))) throw new Error('Invalid sent_at');

  const isSmokeTest = event === 'youtube_production_smoke_test' && testMode === true && sideEffectsAllowed === false;
  const isProduction = event === 'youtube_production_handoff' && testMode === false && sideEffectsAllowed === true;
  if (!isSmokeTest && !isProduction) throw new Error('Handoff mode is not allowed');

  let publicationIssue = '';
  let packageSha = '';
  if (isProduction) {
    publicationIssue = String(body.publication_issue ?? '');
    packageSha = String(body.package_sha ?? '');
    if (!/^\d+$/.test(publicationIssue)) throw new Error('Invalid publication_issue');
    if (!/^[a-f0-9]{64}$/i.test(packageSha)) throw new Error('Invalid package_sha');
    if (typeof body.package_title !== 'string' || !body.package_title.startsWith('YouTube Yayın Paketi - Thumbnail Paketi #')) throw new Error('Invalid package_title');
    if (typeof body.package_url !== 'string' || !body.package_url.startsWith('https://github.com/ErenOzusen/eren-muzik-atolyesi/issues/')) throw new Error('Invalid package_url');
  }

  const idempotencyKey = isProduction
    ? `production:${repository}:${publicationIssue}:${packageSha}`
    : `smoke:${repository}:${runId}:${runAttempt}`;

  return { json: { ...body, validated: true, smoke_test: isSmokeTest, production_allowed: isProduction, idempotency_key: idempotencyKey, github_run_id: runId, publication_issue: publicationIssue, package_sha: packageSha } };
});

const issue = $json;
const handoff = $('Validate GitHub Handoff').item.json;

const expectedIssue = String(handoff.publication_issue ?? '');
const expectedSha = String(handoff.package_sha ?? '').toLowerCase();
const calculatedSha = String(issue.calculated_package_sha ?? '').toLowerCase();
const labels = Array.isArray(issue.labels) ? issue.labels.map(label => typeof label === 'string' ? label : label?.name).filter(Boolean) : [];
const hasLabel = (name) => labels.includes(name);

if (String(issue.number ?? '') !== expectedIssue) throw new Error('Publication issue number mismatch');
if (issue.pull_request) throw new Error('Publication package cannot be a pull request');
if (issue.state !== 'open') throw new Error('Publication issue is not open');
if (typeof issue.title !== 'string' || !issue.title.startsWith('YouTube Yayın Paketi - Thumbnail Paketi #')) throw new Error('Invalid publication package title');
if (hasLabel('sistem-testi')) throw new Error('System-test package cannot enter production');
if (!hasLabel('youtube-yayin-paketi')) throw new Error('youtube-yayin-paketi label is missing');
const publicationApproved = hasLabel('publication-approved') || hasLabel('eren-yayin-onayli');
if (!publicationApproved) throw new Error('Publication approval label is missing');
if (!hasLabel('yayina-hazir')) throw new Error('yayina-hazir label is missing');
if (hasLabel('publication-approval-pending') || hasLabel('eren-yayin-onayi-bekliyor')) throw new Error('Publication approval is still pending');
if (!expectedSha || !calculatedSha || expectedSha !== calculatedSha) throw new Error('Publication package SHA mismatch');
const body = String(issue.body ?? '');
if (!/YOUTUBE_USAGE_V1 test=false .*uploads=0 publications=0/.test(body)) throw new Error('Safe pre-publication usage marker is missing');
if (handoff.package_title && issue.title !== handoff.package_title) throw new Error('Publication package title changed after handoff');
if (handoff.package_url && issue.html_url !== handoff.package_url) throw new Error('Publication package URL mismatch');

return [{ json: { ...issue, publication_package_validated: true, publication_issue: expectedIssue, package_sha: calculatedSha, idempotency_key: handoff.idempotency_key, github_run_id: handoff.github_run_id, repository: handoff.repository, event: handoff.event } }];
